/**
 * @param {number} n
 * @return {number}
 */
var countDigitOne = function(n) {
    let count = 0;
    let m = 1;
    while (m <= n) {
        const higher = Math.floor(n / (m * 10));
        const cur = Math.floor(n / m) % 10;
        const lower = n % m;
        if (cur === 0) {
            count += higher * m;
        } else if (cur === 1) {
            count += higher * m + lower + 1;
        } else {
            count += (higher + 1) * m;
        }
        m *= 10;
    }
    return count;
};
